// ***************
// Filename: pwm_top.sv
// Author: FPGA Cores 4 U
// Description: pwm with its AXI4-Lite register interface, the block designs
//   and testbenches instantiate: the register map pwm_regs (u_regs,
//   src/include/pwm_regs.sv, ID "PWMT", VERSION and DATE at 0x00-0x08, the
//   registers from 0x10) and the logic pwm (u_core, src/pwm.sv), joined by
//   their register ports (cfg_* to the logic, sts_* back). Generated by
//   ip/scripts/regmap_gen.py from pwm_regs.json and the ports of pwm:
//   regenerate after changing either. Clock - aclk. Reset - synchronous
//   active low aresetn.
// Date: 2026-10-12
module pwm_top #(
  parameter int CHANNELS = 4
) (
  input  logic                aclk,
  input  logic                aresetn,
  input  logic [7:0]          s_axil_awaddr,
  input  logic                s_axil_awvalid,
  output logic                s_axil_awready,
  input  logic [31:0]         s_axil_wdata,
  input  logic [3:0]          s_axil_wstrb,
  input  logic                s_axil_wvalid,
  output logic                s_axil_wready,
  output logic [1:0]          s_axil_bresp,
  output logic                s_axil_bvalid,
  input  logic                s_axil_bready,
  input  logic [7:0]          s_axil_araddr,
  input  logic                s_axil_arvalid,
  output logic                s_axil_arready,
  output logic [31:0]         s_axil_rdata,
  output logic [1:0]          s_axil_rresp,
  output logic                s_axil_rvalid,
  input  logic                s_axil_rready,
  output logic [CHANNELS-1:0] pwm_o,
  output logic [CHANNELS-1:0] pwm_n_o,
  output logic                period_pulse_o
);
  // register ports between the register map and the logic
  logic [2:0] cfg_ctrl;
  logic [15:0] cfg_period;
  logic [15:0] cfg_prescale;
  logic [15:0] cfg_deadtime;
  logic [CHANNELS-1:0] cfg_invert;
  logic [CHANNELS*16-1:0] cfg_duty;

  pwm_regs #(
    .CHANNELS(CHANNELS)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(),
    .period_o(cfg_period),
    .period_wr_o(),
    .prescale_o(cfg_prescale),
    .prescale_wr_o(),
    .deadtime_o(cfg_deadtime),
    .deadtime_wr_o(),
    .invert_o(cfg_invert),
    .invert_wr_o(),
    .duty_o(cfg_duty),
    .duty_wr_o()
  );
  pwm #(
    .CHANNELS(CHANNELS)
  ) u_core (
    .aclk,
    .aresetn,
    .pwm_o,
    .pwm_n_o,
    .period_pulse_o,
    .cfg_ctrl,
    .cfg_period,
    .cfg_prescale,
    .cfg_deadtime,
    .cfg_invert,
    .cfg_duty
  );
endmodule
